// İNİŞ YERLERİ: quran.com/api/v4/chapters (revelation_place) ile 114
//   kayıt tek tek doğrulandı; gelenekle farklı surelerde (Ra'd, Hac,
//   İnsân…) kaynak Medine der, onu aldık.
// FAZİLET DİSİPLİNİ: uydurma vaat YOK. Ya sahih/meşhur rivayet ("rivayet
//   edilir" işaretli) ya da surenin öğrettiği amel ahlakına dayalı
//   "okunması güzeldir" tarzı temkinli dil.
// 31.10: bozuk/anlamsız metinler tek tek düzeltildi.
// ════════════════════════════════════════════════════════

import type { SureBilgi } from "./sureData";

export const SURE_BİLGİLERİ_EK: SureBilgi[] = [
  { n: 3, ad: "Âl-i İmrân", inis: "Mekke", konu: "Vahyin haklığı, İmran ailesi ve Meryem kıssası; Uhud'un dersleri.", fazilet: "Bakara'yla birlikte bağışlanma ve sabır duası olarak okunması güzeldir; kıyamette iki büyük sure koruyucu duası olarak rivayet edilir.", nuzul: "Âl-i İmrân Medine döneminde nazil olmuştur. Uhud sonrasında Müslüman topluma sabır, itaat ve ders çıkarma mesajı verir; Ehl-i Kitap ve müşriklerle tevhid/peygamberlik tartışmaları bu bağlamda ele alınır. Mübâhele (3:61) ve dua ayetleri gibi pasajlar Medine siyaset-toplum ilişkileri içinde yorumlanır; ayrıntılı sebep rivayetleri farklı nakledilebilir.", nuzul_en: "Al Imran was revealed in the Madinan period. After Uhud it addresses patience, obedience, and lessons; it also engages People of the Book and polytheists on tawhid and prophethood. Passages such as mubahala (3:61) are read in Madinah’s social-political context; specific occasion reports may vary.", nuzul_ar: "نزلت آل عمران في المدينة. جاءت بعد أحد بدرس الصبر والطاعة، كما تناولت الحوار مع أهل الكتاب والمشركين في التوحيد والنبوة. وتُقرأ آيات مثل المباهلة (3:61) في سياق المدينة، مع اختلاف في بعض روايات السبب.", nuzul_id: "Ali Imran turun di periode Madinah. Setelah Uhud, surah ini memberi pelajaran sabar dan ketaatan; juga membahas dialog dengan Ahli Kitab dan musyrik tentang tauhid dan kenabian. Ayat seperti mubahalah (3:61) dibaca dalam konteks Madinah; laporan sebab khusus dapat berbeda.", nuzul_ur: "سورۃ آل عمران مدنی دور میں نازل ہوئی۔ احد کے بعد صبر، اطاعت اور سبق کا پیغام دیتی ہے؛ اہلِ کتاب و مشرکین سے توحید و نبوت کے مباحث بھی اسی پس منظر میں ہیں۔ مباہلہ (3:61) جیسے مقامات مدنی سیاق میں سمجھے جاتے ہیں؛ اسباب کی روایات مختلف ہو سکتی ہیں۔" },
  { n: 4, ad: "Nisâ", inis: "Medine", konu: "Aile hukuku, miras payları, yetim hakkı ve toplumsal adalet.", fazilet: "Kadın ve yetim haklarını en detaylı veren sure; aile hukukunda 'iyi davranın' emri temel metindir.", nuzul: "Nisâ suresi Medine döneminde nazil olmuştur. Uhud sonrası yetimler, dul kadınlar, miras, nikâh, aile hukuku ve toplum düzeni gibi acil meseleleri ele alır. Adalet, emanet ve zayıfların haklarının korunması Medine toplumunun kuruluş dönemindeki ihtiyaçlarla doğrudan ilişkilidir. Ayrı ayetlere dair özel sebep rivayetleri bulunabilir; ana çerçeve Medine sosyal hukukudur.", nuzul_en: "An-Nisa was revealed in the Madinan period. It addresses urgent issues after Uhud such as orphans, widows, inheritance, marriage, family law, and social order. Justice, trust, and protection of the vulnerable are tied to the needs of the emerging Madinan community. Specific occasion reports exist for some verses; the main frame is Madinan social law.", nuzul_ar: "نزلت النساء في المدينة. عالجت قضايا ملحة بعد أحد كالأيتام والأرامل والمواريث والنكاح وتنظيم الأسرة والمجتمع. ويرتبط العدل وحفظ الحقوق باحتياجات المجتمع المدني الناشئ.", nuzul_id: "An-Nisa turun di Madinah. Ia membahas persoalan mendesak pasca-Uhud seperti yatim, janda, waris, nikah, hukum keluarga, dan ketertiban sosial. Keadilan dan perlindungan pihak lemah terkait kebutuhan masyarakat Madinah yang terbentuk.", nuzul_ur: "سورۃ نساء مدنی دور میں نازل ہوئی۔ احد کے بعد یتیموں، بیواؤں، وراثت، نکاح، خاندانی قانون اور سماجی نظم جیسے فوری مسائل پر ہدایت دیتی ہے۔ انصاف اور کمزوروں کے حقوق مدنی معاشرے کی تشکیل سے جڑے ہیں۔" },
  { n: 5, ad: "Mâide", inis: "Medine", konu: "Ahid ahlakı, dinin ikmali, İsa'nın sofra mucizesi.", fazilet: "'Bugün size dininizi ikmal ettim' beyanıyla dinin bütünlüğü ilan edilir; söz ve ahid ahlakının kaynağıdır.", nuzul: "Mâide Medine döneminde nazil olmuş, Medine’nin son dönem surelerinden sayılır. Ahitlere vefa, helal-haram sınırları, adlî disiplin ve Ehl-i Kitap ile ilişkiler gibi konuları işler. 5:3 ayeti (‘bugün dininizi kemale erdirdim’) Veda Haccı/Arafat bağlamıyla ilişkilendirilir; tarihleme ayrıntıları rivayetlere göre tartışılır. Sure, sözleşme ahlakı ve sorumluluğu vurgular.", nuzul_en: "Al-Ma’idah was revealed in the Madinan period and is counted among later Madinan surahs. It addresses covenants, lawful and unlawful limits, judicial discipline, and relations with People of the Book. Verse 5:3 is associated with the Farewell Pilgrimage/Arafat context; dating details are discussed in reports. The surah emphasizes covenant ethics and responsibility.", nuzul_ar: "نزلت المائدة في المدينة وتُعد من أواخر السور المدنية. تناولت الوفاء بالعقود والحدود والأحكام والعلاقة بأهل الكتاب. وترتبط آية الإكمال (5:3) بسياق حجة الوداع، مع نقاش في بعض تفاصيل التوقيت.", nuzul_id: "Al-Ma’idah turun di Madinah dan termasuk surah Madaniyah akhir. Membahas pemenuhan perjanjian, batas halal-haram, disiplin hukum, dan hubungan dengan Ahli Kitab. Ayat 5:3 dikaitkan dengan konteks Haji Wada‘; rincian waktu dibahas dalam riwayat.", nuzul_ur: "سورۃ مائدہ مدنی دور میں نازل ہوئی اور آخری مدنی سورتوں میں شمار ہوتی ہے۔ عہد کی پابندی، حلال و حرام، قانونی نظم اور اہلِ کتاب سے تعلقات بیان کرتی ہے۔ آیت 5:3 کو حجۃ الوداع/عرفات کے سیاق سے جوڑا جاتا ہے؛ تاریخی تفصیل میں اختلاف ہو سکتا ہے۔" },
  { n: 6, ad: "En'âm", inis: "Mekke", konu: "Tevhid doktrininin tek nefeste sunulması; putperestlik eleştirisi.", fazilet: "Tevhid dersinin en yoğun surelerinden; sahabeler 'büyük sure' diye uzun uzun okumuştur.", nuzul: "En‘âm Mekke döneminde nazil olmuştur ve tevhid akidesini kapsamlı biçimde kurar. Putperest inançlar, kader/yaratıcıya ortak koşma iddiaları ve ahiret inkârı karşısında Allah’ın birliği, delilleri ve peygamberlik mesajı vurgulanır. Rivayetlerde bir gecede/peygamberlik döneminde inişine dair anlatımlar bulunsa da, esas odak içeriğin tevhid merkezliliğidir.", nuzul_en: "Al-An‘am was revealed in the Meccan period and establishes tawhid comprehensively. Against idolatry, claims of partners with God, and denial of the Hereafter, it emphasizes Allah’s oneness, signs, and the prophetic message. Reports about the manner of its revelation exist; the core focus is its monotheistic content.", nuzul_ar: "نزلت الأنعام في مكة وتؤسس للتوحيد إقامة شاملة. ترد على الشرك وإنكار الآخرة بإبراز أدلة وحدانية الله والرسالة. وقد ترد روايات في كيفية نزولها، لكن جوهرها عقدي توحيدي.", nuzul_id: "Al-An‘am turun di Mekah dan membangun akidah tauhid secara komprehensif. Menanggapi syirik dan penolakan akhirat dengan menegaskan keesaan Allah, tanda-tanda-Nya, dan risalah. Ada riwayat tentang cara turunnya; fokus utamanya kandungan tauhid.", nuzul_ur: "سورۃ انعام مکی دور میں نازل ہوئی اور توحید کو جامع انداز میں قائم کرتی ہے۔ شرک اور آخرت کے انکار کے مقابلے میں اللہ کی وحدانیت، دلائل اور رسالت کو واضح کرتی ہے۔ نزول کے طریقے کی روایات مل سکتی ہیں؛ اصل محور توحیدی مضامین ہیں۔" },
  { n: 7, ad: "A'râf", inis: "Mekke", konu: "Âdem ile İblis, Nuh'tan Mûsâ'ya peygamber kıssaları, kıyamet sahneleri.", fazilet: "Kıyamet ve hesap bilincini en kapsamlı resmeden surelerden; tövbe okuması güzeldir.", nuzul: "A‘râf Mekke döneminde nazil olmuştur. Âdem-İblis kıssası, Nuh’tan Şuayb’a peygamber kıssaları ve helak edilen kavimlerin ibretleri üzerinden tevhid, sorumluluk ve ahiret bilinci işlenir. Mekke’de baskı gören müminlere sabır ve tarihî ibret sunar; ‘A‘râf’ sahnesi hesap gününün ayrıntı tasvirlerindendir.", nuzul_en: "Al-A‘raf was revealed in the Meccan period. Through the story of Adam and Iblis and accounts of prophets from Nuh to Shu‘ayb, it teaches tawhid, responsibility, and the Hereafter. It offers patience and lessons to believers under pressure in Mecca; the A‘raf scene depicts aspects of judgment.", nuzul_ar: "نزلت الأعراف في مكة. تعرض قصة آدم وإبليس وقصص الأنبياء من نوح إلى شعيب لتقرير التوحيد والمسؤولية والآخرة. وتقدم صبرا وعبرة للمؤمنين في مكة، ويأتي مشهد الأعراف ضمن تصوير الحساب.", nuzul_id: "Al-A‘raf turun di Mekah. Melalui kisah Adam-Iblis dan para nabi dari Nuh hingga Syu‘aib, surah ini mengajarkan tauhid, tanggung jawab, dan akhirat. Ia memberi kesabaran dan ibrah bagi Mukmin di Mekah; adegan A‘raf menggambarkan aspek hisab.", nuzul_ur: "سورۃ اعراف مکی دور میں نازل ہوئی۔ آدم و ابلیس اور نوح سے شعیب تک انبیاء کے واقعات کے ذریعے توحید، ذمہ داری اور آخرت کا سبق دیتی ہے۔ مکہ کے دباؤ میں مومنوں کو صبر اور عبرت فراہم کرتی ہے؛ اعراف کا منظر حساب کی تصویر بندی کا حصہ ہے۔" },
  { n: 8, ad: "Enfâl", inis: "Medine", konu: "Bedir savaşının dersleri: hazırlık, birlik ve zafer ahlakı.", fazilet: "Toplumsal birlik mesajlarını taşıyan sure; sıkıntılı dönemlerde okunması iyi gelir.", nuzul: "Enfâl Medine döneminde, Bedir Gazvesi (H. 2) sonrası meselelerle ilişkili olarak nazil olmuştur. Ganimetlerin taksimi, savaş disiplini, birlik, Allah’a tevekkül ve zaferin sebepleri ele alınır. Bedir bağlamı siyeri ve tefsirde ayrıntılı anlatılır; ayetler hem tarihî olay hem kalıcı ahlak/strateji ilkeleri taşır.", nuzul_en: "Al-Anfal was revealed in the Madinan period in connection with issues after the Battle of Badr (2 AH). It addresses distribution of spoils, discipline, unity, reliance on Allah, and causes of victory. The Badr context is detailed in sirah and tafsir; the verses carry both historical and enduring ethical lessons.", nuzul_ar: "نزلت الأنفال في المدينة مرتبطة بمسائل بعد بدر (2هـ). تناولت الأنفال والانضباط والوحدة والتوكل وأسباب النصر. ويُفصل سياق بدر في السيرة والتفسير، وتحمل الآيات دروسا تاريخية وأخلاقية.", nuzul_id: "Al-Anfal turun di Madinah terkait persoalan setelah Perang Badar (2 H). Membahas pembagian rampasan, disiplin, persatuan, tawakal, dan sebab kemenangan. Konteks Badar dirinci dalam sirah dan tafsir; ayatnya memuat pelajaran sejarah dan etika abadi.", nuzul_ur: "سورۃ انفال مدنی دور میں غزوۂ بدر (2ھ) کے بعد کے مسائل کے حوالے سے نازل ہوئی۔ غنائم کی تقسیم، نظم و ضبط، اتحاد، توکل اور فتح کے اسباب بیان کرتی ہے۔ بدر کا پس منظر سیرت و تفسیر میں مفصل ہے؛ آیات تاریخی اور دائمی اخلاقی اصول دونوں رکھتی ہیں۔" },
  { n: 9, ad: "Tevbe", inis: "Medine", konu: "Münafıklık eleştirisi, Tebük seferi ve tövbe müjdesi — besmelesiz sure.", fazilet: "Tövbe kapısının hiç kapanmadığını beyan eden sure; istiğfar vurgularıyla okunması güzeldir.", nuzul: "Tevbe Medine döneminde, özellikle H. 9 civarındaki sefer/siyasî gelişmeler ve ahit ihlalleri bağlamında nazil olmuştur. Tebük, münafıkların tavırları, ahitlere bağlılık/ihlal ve tövbe kapısının açıklığı temel konulardandır. Sure besmele ile başlamaz; bu durumun hikmeti üzerinde farklı değerlendirmeler vardır, rivayetleri ihtiyatla okumak gerekir.", nuzul_en: "At-Tawbah was revealed in the Madinan period, connected to events around 9 AH including Tabuk, treaty violations, and attitudes of hypocrites. Loyalty to covenants, accountability, and the openness of repentance are central. It does not begin with the basmalah; explanations differ and should be read carefully.", nuzul_ar: "نزلت التوبة في المدينة مرتبطة بأحداث نحو 9هـ كتبوك ونقض العهود ومواقف المنافقين. محاورها الوفاء بالعهد والمساءلة وسعة التوبة. ولا تبدأ بالبسملة، وتختلف الآراء في الحكمة.", nuzul_id: "At-Taubah turun di Madinah terkait peristiwa sekitar 9 H termasuk Tabuk, pelanggaran perjanjian, dan sikap munafik. Kesetiaan pada perjanjian, pertanggungjawaban, dan pintu tobat menjadi pusat. Surah ini tidak diawali basmalah; penjelasan hikmahnya beragam.", nuzul_ur: "سورۃ توبہ مدنی دور میں 9ھ کے قریب تبوک، عہد شکنیوں اور منافقین کے رویوں کے پس منظر میں نازل ہوئی۔ عہد کی پابندی، جوابدہی اور توبہ کا دروازہ اہم مضامین ہیں۔ یہ بسم اللہ سے شروع نہیں ہوتی؛ حکمت پر آراء مختلف ہیں۔" },
  { n: 10, ad: "Yûnus", inis: "Mekke", konu: "Vahyin haklığı, Nûh ve Yûnus kıssaları; Kur'an'ın belde insanına daveti.", fazilet: "Yûnus'un balık karnındaki duası darlıktan çıkış duası olarak rivayetle okunur.", nuzul: "Yûnus Mekke döneminde nazil olmuştur. Mekke müşriklerine vahyin hakikati, peygamberliğin delilleri ve ahiret uyarısı sunulur; Nuh ve Musa/Firavun gibi kıssalar ibret olarak anılır. Yunus peygamberin kavmine dönük müjde (10:98) ümide yer açar. Sure, tebliğe karşı inat ve kabul arasında insan tutumlarını tartışır.", nuzul_en: "Yunus was revealed in the Meccan period. It presents the truth of revelation, signs of prophethood, and warning of the Hereafter to Meccan opponents; stories of Nuh and Musa/Pharaoh serve as lessons. The mention of Yunus’s people (10:98) offers hope. It contrasts rejection and acceptance of the message.", nuzul_ar: "نزلت يونس في مكة. تعرض حقيقة الوحي ودلائل النبوة والإنذار بالآخرة، وتذكر قصص نوح وموسى وفرعون للعبرة. وفيها إشارة رجاء في قوم يونس (10:98).", nuzul_id: "Yunus turun di Mekah. Menyampaikan kebenaran wahyu, tanda kenabian, dan peringatan akhirat; kisah Nuh serta Musa/Fir‘aun menjadi ibrah. Penyebutan kaum Yunus (10:98) memberi harapan.", nuzul_ur: "سورۃ یونس مکی دور میں نازل ہوئی۔ وحی کی حقیقت، نبوت کے دلائل اور آخرت کی تنبیہ پیش کرتی ہے؛ نوح اور موسیٰ/فرعون کے واقعات عبرت ہیں۔ قومِ یونس کا ذکر (10:98) امید کا پہلو رکھتا ہے۔" },
  { n: 11, ad: "Hûd", inis: "Mekke", konu: "Peygamberlerin ortak sabır imtihanı; istikamet vurgusu.", fazilet: "Peygamberimiz 'Hûd ve benzerleri beni yaşlandırdı' demiştir (Buhârî-Müslim); ağır ve titiz okunur.", nuzul: "Hûd Mekke döneminde, özellikle Hüzün Yılı çevresindeki baskı döneminde teselli ve sebat mesajı taşıdığı rivayet edilir (Hz. Peygamber’in ‘Hûd beni ihtiyarlattı’ sözü hadis kaynaklarında geçer; bağlam tefsirde açıklanır). Nuh, Hûd, Salih, İbrahim, Lut, Şuayb ve Musa kıssalarıyla peygamberlerin sebatı ve kavimlerin akıbeti işlenir; 11:112 istikamet çağrısı merkezidir.", nuzul_en: "Hud was revealed in the Meccan period and is associated with consolation and steadfastness during hardship. The Prophet’s statement that Hud and similar surahs aged him is reported in hadith sources and discussed in tafsir. Stories of prophets from Nuh to Musa highlight perseverance and consequences; 11:112 calls to steadfastness.", nuzul_ar: "نزلت هود في مكة وترتبط بالصبر والتثبيت في الشدة. ويُروى أثر عن النبي في شأن هود والسور المشابهة. وتعرض قصص الأنبياء وتختم بدعوة الاستقامة (11:112).", nuzul_id: "Hud turun di Mekah dan dikaitkan dengan keteguhan di masa sulit. Ada riwayat sabda Nabi tentang Hud dan surah serupa. Kisah para nabi menekankan kesabaran; 11:112 menyerukan istiqamah.", nuzul_ur: "سورۃ ہود مکی دور میں نازل ہوئی اور سختی کے زمانے میں ثبات کی تعلیم دیتی ہے۔ ہود اور ملتی جلتی سورتوں کے بارے میں مروی اثر کی تفسیر کی جاتی ہے۔ انبیاء کے واقعات صبر اور انجام دکھاتے ہیں؛ 11:112 استقامت کی دعوت ہے۔" },
  { n: 13, ad: "Ra'd", inis: "Medine", konu: "Allah'ın kudret tasvirleri; kalbin zikirle huzuru.", fazilet: "'Kalbler ancak Allah'ı anmakla huzur bulur' ayeti huzur arayanların okuması güzeldir.", nuzul: "Ra‘d suresi iniş yeri hakkında Mekke ve Medine rivayetleri vardır. Tevhid, peygamberlik ve ahiret delilleri ile kalplerin huzurunun Allah’ın zikriyle olduğu vurgulanır (13:28). Peygamberin ve müminlerin zorluklar karşısındaki sabrı Mekke tebliğinin genel iklimiyle uyumludur; bazı ayetlerin Medine bağlantılı ele alındığı görüşler de bulunur.", nuzul_en: "Ar-Ra‘d is reported with both Meccan and Medinan attributions. It emphasizes signs of tawhid, prophethood, and the Hereafter, and states that hearts find rest in remembrance of Allah (13:28). Its call to patience fits the pressures of proclamation; some hold Medinan links for parts of it.", nuzul_ar: "تُذكر الرعد بمكي ومدني. تؤكد دلائل التوحيد والرسالة والآخرة وأن القلوب تطمئن بذكر الله (13:28).", nuzul_id: "Ar-Ra‘d diriwayatkan dengan atribusi Mekah dan Madinah. Menegaskan tanda tauhid, kenabian, akhirat, dan ketenangan hati dengan zikir (13:28).", nuzul_ur: "سورۃ الرعد کے نزول میں مکی اور مدنی اقوال ہیں۔ توحید، رسالت، آخرت کے دلائل اور ذکرِ الٰہی سے دلوں کا اطمینان (13:28) بیان کرتی ہے۔" },
  { n: 14, ad: "İbrâhîm", inis: "Mekke", konu: "Vahyin kitap olarak gücü; İbrahim'in Kâbe ve evlâd duaları.", fazilet: "İbrahim'in evlâd ve ümmet duaları ebeveyn duası olarak okunur; 'kalb-i selim' duası buradandır.", nuzul: "İbrâhîm suresi Mekke döneminde nazil olmuştur. Nimet, şükür ve inkârın sonuçları, önceki peygamberlerin tebliği ve Hz. İbrahim’in duası üzerinden tevhid ve ahiret bilinci işlenir. Dil ve vahyin insanlığa ulaşması (14:4) ile toplumsal sorumluluk vurgusu, Mekke muhataplarına yönelik ikaz ve ibret taşır.", nuzul_en: "Ibrahim was revealed in the Meccan period. Through gratitude versus ingratitude, earlier messengers, and Abraham’s supplication, it teaches tawhid and accountability. The role of language and revelation (14:4) carries warning and lesson for its audience.", nuzul_ar: "نزلت إبراهيم في مكة. تعالج الشكر والكفر وعواقبهما وقصص الرسل ودعاء إبراهيم، مؤكدة التوحيد والآخرة.", nuzul_id: "Ibrahim turun di Mekah. Melalui syukur dan kufur, kisah rasul, dan doa Ibrahim, surah ini mengajarkan tauhid dan pertanggungjawaban.", nuzul_ur: "سورۃ ابراہیم مکی دور میں نازل ہوئی۔ شکر و کفر کے انجام، سابق رسولوں اور ابراہیم کی دعا کے ذریعے توحید اور جوابدہی کا درس دیتی ہے۔" },
  { n: 15, ad: "Hicr", inis: "Mekke", konu: "Ashâb-ı Hicr'ın akıbeti; 'Kur'an'ı bölüm bölüm indirdik' müjdesi.", fazilet: "'Biz seni unutanlardan değiliz' beyanı hafızlık yolculuğuna moraldir.", nuzul: "Hicr suresi Mekke döneminde nazil olmuştur. Vahyin korunacağı müjdesi (15:9), inkârcıların tutumu ve önceki kavimlerin akıbeti (Hicr/Sâlih kavmi gibi) Mekke tebliğinde sabır ve güven verir. ‘Sabredenlerle beraber secde edenlerden ol’ çağrısı (15:98) baskı ortamında ibadete sarılmayı öğütler.", nuzul_en: "Al-Hijr was revealed in the Meccan period. It gives assurance of the Qur’an’s preservation (15:9), recounts responses of deniers and fates of earlier peoples, and calls to patience and worship under pressure (15:98).", nuzul_ar: "نزلت الحجر في مكة. تبشر بحفظ الذكر (15:9) وتعرض مواقف المكذبين وعواقب الأمم، وتأمر بالصبر والسجود (15:98).", nuzul_id: "Al-Hijr turun di Mekah. Menjamin terjaganya Al-Qur’an (15:9), menceritakan penentang dan umat terdahulu, serta menyeru sabar dan sujud (15:98).", nuzul_ur: "سورۃ حجر مکی دور میں نازل ہوئی۔ قرآن کی حفاظت کی بشارت (15:9)، جھٹلانے والوں کے رویے اور سابق قوموں کے انجام بیان کرتی ہے، صبر و سجدے کی تلقین کرتی ہے (15:98)۔" },
  { n: 16, ad: "Nahl", inis: "Mekke", konu: "Bal arısı, deve, su, gece-gündüz — nimetler tek tek sayılır.", fazilet: "Nimetleri düşünmeye davetin en zengin surelerinden; şükür alışkanlığı için okunması güzel.", nuzul: "Nahl suresi Mekke döneminde nazil olmuştur. Yaratılıştaki nimetler ve deliller üzerinden tevhid ispatlanır; müşriklerin bahaneleri cevaplanır. Son ayetlerde hicret/sabır ve güzel mücadele adabına dair ilkeler bulunur (16:41, 125-128); bu ayetlerin nüzul zamanlaması hakkında tefsirde tartışma olsa da sure genel olarak Mekke bağlamındadır.", nuzul_en: "An-Nahl was revealed in the Meccan period. It argues for tawhid through blessings and signs in creation and answers objections. Its closing guidance on patience and goodly invitation (16:125–128) is read within the Meccan context, though timing details of some verses are discussed.", nuzul_ar: "نزلت النحل في مكة. تستدل بالنعم والآيات على التوحيد وترد الشبهات، وتختم بهدي الصبر والدعوة بالحسنى.", nuzul_id: "An-Nahl turun di Mekah. Berdalil pada nikmat dan tanda ciptaan untuk tauhid, menjawab sanggahan, dan menutup dengan sabar serta dakwah yang baik.", nuzul_ur: "سورۃ نحل مکی دور میں نازل ہوئی۔ نعمتوں اور نشانیوں سے توحید کا استدلال کرتی ہے، اعتراضات کے جواب دیتی ہے، صبر اور حسن دعوت کی ہدایت پر ختم ہوتی ہے۔" },
  { n: 17, ad: "İsrâ", inis: "Mekke", konu: "Mirâc gecesi, İsrâiloğulları'nın iki kez bozgunu; anne-babaya iyilik.", fazilet: "Anne-babaya dua olan 'Rabbi-rhamhumâ kemâ rabbeytânî sağîrâ' ayeti ebeveyn duası olarak okunur; Mirâc gecesiyle mübarek surelerdendir.", nuzul: "İsrâ (Benî İsrâil) suresi Mekke döneminde nazil olmuştur. İsra’dan işaretle başlayan sure (17:1), Mescid-i Haram’dan Mescid-i Aksa’ya gece yolculuğu bağlamında tefekkür ve tevhid mesajı verir. Beni İsrail’e ibretler, ahlak ilkeleri ve ibadet emri Mekke baskısında müminlere yön tayin eder. İsra’nın zamanı hakkında rivayet farklılıkları vardır.", nuzul_en: "Al-Isra was revealed in the Meccan period. Beginning with the Night Journey (17:1), it conveys reflection and tawhid, lessons for the Children of Israel, moral principles, and guidance for worship under Meccan pressure. Reports differ on the timing of the Isra journey.", nuzul_ar: "نزلت الإسراء في مكة. تبدأ بالإسراء (17:1) وتجمع العبرة لبني إسرائيل والأخلاق والهداية للعبادة في سياق الضغط المكي.", nuzul_id: "Al-Isra turun di Mekah. Dimulai dengan Isra (17:1), memuat ibrah Bani Israil, prinsip akhlak, dan petunjuk ibadah di tengah tekanan Mekah.", nuzul_ur: "سورۃ اسراء مکی دور میں نازل ہوئی۔ اسراء (17:1) سے آغاز، بنی اسرائیل کے لیے عبرت، اخلاقی اصول اور مکی دباؤ میں عبادت کی رہنمائی بیان کرتی ہے۔" },
  { n: 20, ad: "Tâhâ", inis: "Mekke", konu: "Mûsâ'nın seçilişi, Firavun kıssası ve elçilik kaygısı.", fazilet: "Hz. Ömer'in İslam'a girişine vesile olduğu rivayet edilir; 'seni sevdim' hitabı umut verir.", nuzul: "Tâ-Hâ Mekke döneminde nazil olmuştur. Hz. Musa’nın kıssası uzun biçimde anlatılarak tebliğde sabır, Allah’a güven ve doğru söz örneklenir. Mekke’de Kur’an’ı ağır bulanlara karşı vahyin hikmetini hatırlatır. Hz. Ömer’in Müslüman oluşu bağlamında bu surenin okunduğu rivayet edilir; rivayet ayrıntıları kaynaklarda çeşitlidir.", nuzul_en: "Ta-Ha was revealed in the Meccan period. The extended account of Moses models patience, trust in Allah, and clarity in conveying the message. It reminds opponents of the wisdom of revelation. A report connects Umar’s acceptance of Islam to hearing this surah; details vary across sources.", nuzul_ar: "نزلت طه في مكة. تعرض قصة موسى مفصلة نموذجا للصبر والتوكل والبلاغ، وتذكر بحكمة الوحي. وتُروى قصة ارتباطها بإسلام عمر مع اختلاف في التفاصيل.", nuzul_id: "Taha turun di Mekah. Kisah Musa yang panjang mencontohkan sabar, tawakal, dan kejelasan dakwah. Ada riwayat keterkaitan dengan masuk Islamnya Umar; rinciannya berbeda.", nuzul_ur: "سورۃ طٰہٰ مکی دور میں نازل ہوئی۔ حضرت موسیٰ کا مفصل واقعہ صبر، توکل اور تبلیغ کی مثال دیتا ہے۔ حضرت عمر کے اسلام لانے کے ساتھ اس کی تلاوت کی روایت ملتی ہے؛ تفصیل مختلف ہے۔" },
  { n: 21, ad: "Enbiyâ", inis: "Mekke", konu: "Peygamber kıssaları; 'âlemlere rahmet' müjdesi ve kıyamet yakınlığı.", fazilet: "21:107 'âlemlere rahmet' beyanı salavat ve Peygamber sevgisinde sık referanstır.", nuzul: "Enbiyâ Mekke döneminde nazil olmuştur. Peygamberlerin ortak mesajı, müşrik itirazları ve ahiret sahneleri üzerinden tevhid vurgulanır. ‘Biz seni alemlere rahmet olarak gönderdik’ (21:107) ayeti Nebi’nin evrensel rahmet misyonunu bildirir. Kıssalar, Mekke’de yalnızlık ve baskı yaşayan müminlere tarihî destek sunar.", nuzul_en: "Al-Anbiya was revealed in the Meccan period. It emphasizes the shared message of prophets, answers objections, and depicts the Hereafter. Verse 21:107 states the Prophet was sent as mercy to the worlds. The narratives support believers facing isolation and pressure in Mecca.", nuzul_ar: "نزلت الأنبياء في مكة. تؤكد وحدة دعوة الأنبياء وترد الشبهات وتصور الآخرة، وفيها أن النبي رحمة للعالمين (21:107).", nuzul_id: "Al-Anbiya turun di Mekah. Menegaskan pesan para nabi, menjawab sanggahan, dan menggambarkan akhirat. Ayat 21:107 menyatakan Nabi sebagai rahmat bagi semesta.", nuzul_ur: "سورۃ انبیاء مکی دور میں نازل ہوئی۔ انبیاء کے مشترک پیغام، اعتراضات کے جواب اور آخرت کی تصویریں پیش کرتی ہے۔ 21:107 میں نبی کی رحمت للعالمین حیثیت بیان ہے۔" },
  { n: 22, ad: "Hac", inis: "Medine", konu: "Hac ibadeti; kıyamet ve diriliş tasvirleri — iki secde ayetli tek sure.", fazilet: "Tilavet secdesi iki kez gelir; hac mevsiminde okunması güzeldir.", nuzul: "Hac suresi iniş bakımından Mekke ve Medine ayetleri içerdiği kabul edilir; hac ibadeti, kıyamet ve mücadele/izin ayetleri farklı dönem bağlamlarıyla okunur. Büyük hac/küçük hac tartışmaları ve savaş izniyle ilgili ayetlerin nüzul zamanlaması tefsirde ele alınır. Sure, Allah’a saygı, ibadet disiplini ve adalet çağrısını birleştirir.", nuzul_en: "Al-Hajj is understood to include both Meccan and Medinan verses. Rites of pilgrimage, resurrection, and verses related to struggle/permission are read in their contexts; scholars discuss timing of specific verses. The surah unites reverence for Allah, worship, and justice.", nuzul_ar: "تجمع الحج آيات مكية ومدنية في قول كثير. تعرض مناسك الحج والبعث وآيات متعلقة بالإذن/الجهاد بسياقاتها، مع نقاش في توقيت بعض الآيات.", nuzul_id: "Al-Hajj dipahami memuat ayat Mekah dan Madinah. Membahas manasik haji, kebangkitan, dan ayat terkait izin/ perjuangan dalam konteksnya; waktu sebagian ayat dibahas ulama.", nuzul_ur: "سورۃ حج میں مکی اور مدنی آیات دونوں مانی جاتی ہیں۔ حج کے مناسک، بعث اور قتال/اجازت سے متعلق آیات اپنے سیاق میں پڑھی جاتی ہیں؛ بعض آیات کے وقت نزول پر بحث ہے۔" },
  { n: 23, ad: "Mü'minûn", inis: "Mekke", konu: "Müminin karakter tanımı: namaz, gafletsizlik, emanet, hayâ.", fazilet: "Açılıştaki sekiz özellik listesi mümin karakterinin en özlü tarifidir; okunması güzel.", nuzul: "Mü’minûn suresi Mekke döneminde nazil olmuştur. Müminlerin özellikleriyle açılır (23:1-11), ardından yaratılış delilleri, peygamber kıssaları ve ahiret sahneleri gelir. Mekke’de kimlik ve ahlak inşası için bir program sunar: namaz, iffet, emanet, sözünde durma ve ahiret bilinci.", nuzul_en: "Al-Mu’minun was revealed in the Meccan period. It opens with traits of believers (23:1–11), then presents signs of creation, prophetic stories, and the Hereafter. It offers a program of character and faith for believers in Mecca.", nuzul_ar: "نزلت المؤمنون في مكة. تبدأ بصفات المؤمنين (23:1-11) ثم تعرض أدلة الخلق وقصص الأنبياء والآخرة، مقدمة بناء إيمانيا وأخلاقيا.", nuzul_id: "Al-Mu’minun turun di Mekah. Dibuka dengan sifat Mukmin (23:1–11), lalu tanda penciptaan, kisah nabi, dan akhirat—membangun iman dan akhlak.", nuzul_ur: "سورۃ مومنون مکی دور میں نازل ہوئی۔ مومنوں کی صفات (23:1–11) سے آغاز، پھر تخلیق کے دلائل، انبیاء کے واقعات اور آخرت—ایمان و کردار کی تعمیر۔" },
  { n: 25, ad: "Furkan", inis: "Mekke", konu: "Hak-batıl ayırımı; İbâd-ur-Rahmân'ın nitelikleri.", fazilet: "Karakter davranış listesi olarak okunur; toplum ahlakının cetveli sayılır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Hak ile batılı ayıran bir furkan olarak Kur’an’ı savunur, müşrik itirazlarına cevap verir; Rahman’ın kulları için ahlak ölçüleri sunar.", nuzul_en: "This surah was revealed in the Meccan period. It distinguishes truth from falsehood and responds to objections against the Qur’an and the Prophet, emphasizing servanthood to the Most Merciful and moral character.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تفرق بين الحق والباطل وترد شبهات حول القرآن والنبي، وتؤكد العبودية للرحمن والأخلاق.", nuzul_id: "Surah ini turun pada periode Mekah. Membedakan hak dan batil, menjawab sanggahan terhadap Al-Qur’an dan Nabi, serta menekankan pengabdian kepada Ar-Rahman dan akhlak.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ حق و باطل میں فرق کرتی ہے، قرآن و نبی پر اعتراضات کے جواب دیتی ہے، رحمن کی بندگی اور اخلاق پر زور دیتی ہے۔" },
  { n: 26, ad: "Şuarâ", inis: "Mekke", konu: "Peygamber kıssaları; 'ben şair değilim' tevhid beyanı.", fazilet: "Peygamberlerin gündelik izdihamlardan teselli mesajları yorgun davetçilere okunur.", nuzul: "Bu surenin iniş yeri hakkında farklı rivayetler bulunur; tefsirlerde tartışılır. Peygamber kıssalarıyla Hz. Peygamber’i teselli eder, tebliğin zorluğunda sabır ve tevekkül öğretir; inkâr edenlere ibret sunar.", nuzul_en: "This surah was revealed in the Meccan period. It recounts prophetic stories to console the Prophet and warn deniers, highlighting reliance on Allah and the truth of revelation.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تعرض قصص الأنبياء تثبيتا للنبي وإنذارا للمكذبين، مع التوكل على الله وصدق الوحي.", nuzul_id: "Surah ini turun pada periode Mekah. Menceritakan kisah para nabi untuk menghibur Nabi dan memperingatkan para pendusta, menonjolkan tawakal dan kebenaran wahyu.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ انبیاء کے واقعات نبی کی تسلی اور جھٹلانے والوں کی تنبیہ کے لیے بیان کرتی ہے، توکل اور وحی کی سچائی نمایاں ہے۔" },
  { n: 27, ad: "Neml", inis: "Mekke", konu: "Süleyman'ın karınca-hudhud hikmeti; Sebe melikesinin imânı.", fazilet: "Karının hitap dili, alçak bir canlının bile düşünme kabiliyetini gösterir; akıl dersidir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It presents narratives of Moses and Solomon as signs of divine knowledge and power, calling to worship Allah alone.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تعرض قصتي موسى وسليمان دلالة على علم الله وقدرته، وتدعو إلى عبادة الله وحده.", nuzul_id: "Surah ini turun pada periode Mekah. Menyajikan kisah Musa dan Sulaiman sebagai tanda ilmu dan kekuasaan Allah, menyeru ibadah hanya kepada-Nya.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ موسیٰ اور سلیمان کے واقعات اللہ کے علم و قدرت کی نشانیوں کے طور پر پیش کرتی ہے، خالص عبادت کی دعوت دیتی ہے۔" },
  { n: 28, ad: "Kasas", inis: "Mekke", konu: "Mûsâ'nın bebeklik hikâyesi, Medyen dönemi; 'bu dünyanın kimin' sorgusu.", fazilet: "Allah'ın planı insandan üstündür müjdesi kaygılı kalbe okunur.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It tells the detailed story of Moses, drawing lessons on divine plan, patience, and the Hereafter for believers facing hardship.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تعرض قصة موسى مفصلة دروسا في تدبير الله والصبر والآخرة للمؤمنين في الشدة.", nuzul_id: "Surah ini turun pada periode Mekah. Menceritakan kisah Musa secara rinci, memberi pelajaran tentang rencana Allah, sabar, dan akhirat bagi Mukmin yang tertekan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ موسیٰ کا مفصل واقعہ اللہ کی تدبیر، صبر اور آخرت کے اسباق دیتا ہے، خاص طور پر سختی میں مومنوں کے لیے۔" },
  { n: 29, ad: "Ankebût", inis: "Mekke", konu: "İmmanın sınaması; örümcek ağı misali, Nûh-İbrahim-Lût kıssaları.", fazilet: "Allah'tan başka velinin 'örümcek ağı' benzetmesi, imtihan dönemlerinde okunur.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Bazı ayetlerin iniş zamanı/mekânı tefsirde tartışılır. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It tests the claim of faith through trials and recounts earlier communities, affirming that hardship can refine belief; timing/place discussions appear in tafsir for some verses.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تبتلي دعوى الإيمان وتذكر الأمم السابقة، مؤكدة أن الابتلاء يمحص الإيمان؛ وتُناقش تفاصيل زمان/مكان لبعض الآيات.", nuzul_id: "Surah ini turun pada periode Mekah. Menguji klaim iman melalui cobaan dan kisah umat terdahulu; detail waktu/tempat sebagian ayat dibahas dalam tafsir.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ ایمان کے دعوے کو آزمائشوں اور سابق امتوں کے ذکر سے پرکھتی ہے؛ بعض آیات کے زمان/مقام پر تفسیری بحث ہے۔" },
  { n: 30, ad: "Rûm", inis: "Mekke", konu: "Bizans'ın yenilgisi ve fethi haberi; iki doğu-iki batı ve evlilik ayeti.", fazilet: "30:21 evlilik ayeti nikâh konuşmalarında sık referanstır; sevgi ve huzur tanımı buradadır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It opens with the Romans’ defeat and later victory as a sign within divine decree, then reflects on creation, human nature, and resurrection.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تفتتح بغلبة الروم ثم غلبتهم آية في القضاء الإلهي، ثم تتأمل الخلق والفطرة والبعث.", nuzul_id: "Surah ini turun pada periode Mekah. Dibuka dengan kekalahan lalu kemenangan Romawi sebagai tanda takdir, lalu merenungkan ciptaan, fitrah, dan kebangkitan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ روم کی شکست پھر فتح کو الٰہی تقدیر کی نشانی کے طور پر بیان کرتی ہے، پھر تخلیق، فطرت اور بعث پر غور دلاتی ہے۔" },
  { n: 31, ad: "Lokmân", inis: "Mekke", konu: "Lokmân'ın oğluna vasiyeti: şirk, anne-baba, namaz, sabır, tevazu.", fazilet: "Ebeveynlik vasiyetinin en özlü tarifi; gençlere okunması iyi bir eğitimdir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It conveys Luqman’s wise counsel to his son, grounding ethics in tawhid, gratitude, and humility.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تنقل حكمة لقمان لابنه مؤسسة للأخلاق على التوحيد والشكر والتواضع.", nuzul_id: "Surah ini turun pada periode Mekah. Menyampaikan nasihat bijak Luqman kepada anaknya, mendasarkan etika pada tauhid, syukur, dan rendah hati.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ لقمان کی حکیمانہ نصیحت بیان کرتی ہے، اخلاق کو توحید، شکر اور تواضع پر قائم کرتی ہے۔" },
  { n: 32, ad: "Secde", inis: "Mekke", konu: "Yaratılış ve sınırlı ömür; uyku bir ölüm misali.", fazilet: "Tilavet secdesi düşer; uyku-ölüm benzetmesi sabah-akşam okumaya elverişlidir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It emphasizes revelation, human creation, resurrection, and the distinction between believers who prostrate and those who turn away.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد الوحي وخلق الإنسان والبعث والفرق بين الساجدين والمعرضين.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan wahyu, penciptaan manusia, kebangkitan, dan perbedaan antara yang bersujud dan yang berpaling.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ وحی، انسانی تخلیق، بعث اور سجدہ کرنے والوں و منہ موڑنے والوں کا فرق واضح کرتی ہے۔" },
  { n: 33, ad: "Ahzâb", inis: "Medine", konu: "Hendek savaşı, evlilik ahlakı, Peygamber'in aile hükümleri.", fazilet: "33:56 salavat ayetinin bulunduğu sure: 'Allah ve melekleri ona salavat ediyor' — salavat zikrinin Kur'an temeli.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It addresses family, community, and prophetic household matters in Madinah, including social ethics and responsibilities.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تعالج شؤون الأسرة والمجتمع وبيت النبوة في المدينة، مع أخلاق اجتماعية ومسؤوليات.", nuzul_id: "Surah ini turun pada periode Madinah. Membahas urusan keluarga, masyarakat, dan rumah tangga Nabi di Madinah, termasuk etika dan tanggung jawab sosial.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ مدینہ میں خاندان، معاشرہ اور اہلِ بیتِ نبوی سے متعلق امور، سماجی اخلاق اور ذمہ داریاں بیان کرتی ہے۔" },
  { n: 34, ad: "Sebe", inis: "Mekke", konu: "Sebe halkının nimetleri ve akibeti; şükür-nankörlük karşıtlığı.", fazilet: "'Şükrederseniz artırırım' prensibinin en net anlatıldığı surelerden.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It contrasts gratitude and denial through the people of Saba and affirms accountability, resurrection, and Allah’s knowledge.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقابل بين الشكر والكفر بقصة سبأ وتؤكد الحساب والبعث وعلم الله.", nuzul_id: "Surah ini turun pada periode Mekah. Membandingkan syukur dan kufur melalui kaum Saba serta menegaskan hisab, kebangkitan, dan ilmu Allah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ سبا کے واقعے سے شکر و کفر کا موازنہ کرتی ہے، حساب، بعث اور اللہ کے علم کی تاکید کرتی ہے۔" },
  { n: 35, ad: "Fâtır", inis: "Mekke", konu: "Allah'ın Fâtır (yaratıcı) olması; meleklerin görev düzeni.", fazilet: "'Hamd ile Allah'ı anmak' dersini sistematik sunar; sabah okuması güzel.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It highlights Allah as Creator and Provider, the role of angels, and the differing ends of people based on faith and deeds.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تبرز الله خالقا ورازقا ودور الملائكة واختلاف مصائر الناس بحسب الإيمان والعمل.", nuzul_id: "Surah ini turun pada periode Mekah. Menonjolkan Allah sebagai Pencipta dan Pemberi rezeki, peran malaikat, dan akhir manusia menurut iman-amal.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ اللہ کو خالق و رازق، فرشتوں کے کردار اور ایمان و عمل کے مطابق انجام کے اختلاف کو نمایاں کرتی ہے۔" },
  { n: 37, ad: "Sâffât", inis: "Mekke", konu: "Meleklerin saf düzeni, peygamber kurtuluşları, cennet ziyafetleri.", fazilet: "'Saf bağlayın' ruhu cemaat ahlakını öğretir; kıyamet derslerinin en hareketli anlatımından.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms the sincerity of prophets, rejects false deities, and depicts scenes of judgment and reward.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد إخلاص المرسلين وترفض الآلهة الباطلة وتصور مشاهد الجزاء.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan keikhlasan para rasul, menolak sesembahan batil, dan menggambarkan balasan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ رسولوں کی اخلاص، باطل معبودوں کی تردید اور جزا کے مناظر پیش کرتی ہے۔" },
  { n: 38, ad: "Sâd", inis: "Mekke", konu: "Dâvûd-Süleyman imtihanı; Eyyûb'un sabrı.", fazilet: "Eyyûb'un 'darlık gerçekten bana dokundu' duası sıkıntılı günlerin duasıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It reviews prophetic trials (including David and Solomon) to teach patience, repentance, and devotion to Allah.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تستعرض ابتلاءات الأنبياء (منهم داود وسليمان) لتعليم الصبر والتوبة والإخلاص.", nuzul_id: "Surah ini turun pada periode Mekah. Mengulas ujian para nabi (termasuk Dawud dan Sulaiman) untuk mengajarkan sabar, tobat, dan keikhlasan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ انبیاء کی آزمائشوں (داؤد و سلیمان سمیت) سے صبر، توبہ اور اخلاص سکھاتی ہے۔" },
  { n: 39, ad: "Zümer", inis: "Mekke", konu: "Kıyamet sahneleri; 'Allah'ın affı her şeyden büyüktür' müjdesi.", fazilet: "Günahkârı umutlandıran en yoğun sure; tövbe kapısının açık olduğunu ispat eder.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It calls to sincere worship, contrasts outcomes of belief and denial, and offers hope through repentance.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدعو إلى إخلاص العبادة وتقابل عاقبة الإيمان والكفر وتبشر بالتوبة.", nuzul_id: "Surah ini turun pada periode Mekah. Menyeru ibadah ikhlas, membandingkan akibat iman dan ingkar, serta memberi harapan tobat.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ خالص عبادت کی دعوت، ایمان و انکار کے انجام کا موازنہ اور توبہ کی امید دیتی ہے۔" },
  { n: 40, ad: "Mü'min", inis: "Mekke", konu: "Firavun sarayında gizlice iman eden adamın cesaretli savunması.", fazilet: "Baskı altında imanını saklamayan adam modeli; zor dönem müminlerine okunur.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It presents the believing man among Pharaoh’s people and affirms divine support for messengers and consequences for arrogance.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تعرض مؤمن آل فرعون وتؤكد نصر الله للرسل وعاقبة الاستكبار.", nuzul_id: "Surah ini turun pada periode Mekah. Menyajikan lelaki Mukmin dari kaum Fir‘aun, menegaskan pertolongan Allah bagi rasul dan akibat kesombongan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ آلِ فرعون کے مومن کا ذکر، رسولوں کی مدد اور تکبر کے انجام کی تاکید کرتی ہے۔" },
  { n: 41, ad: "Fussilet", inis: "Mekke", konu: "Vahyin bölümlere ayrılması; tartışma anında güzel söz ahlakı.", fazilet: "'Güzel sözle mücadele et' ilkesi kamusal tartışma ahlakının ilacıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It defends the Qur’an as clear guidance and calls to good speech and steadfastness in inviting to Allah.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدافع عن القرآن هدى مبينا وتدعو إلى الكلمة الحسنة والثبات في الدعوة إلى الله.", nuzul_id: "Surah ini turun pada periode Mekah. Membela Al-Qur’an sebagai petunjuk jelas dan menyeru ucapan baik serta keteguhan dalam dakwah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قرآن کو واضح ہدایت قرار دیتی ہے اور اچھے کلام و دعوت میں استقامت کی ترغیب دیتی ہے۔" },
  { n: 42, ad: "Şûrâ", inis: "Mekke", konu: "İstişare ilkesi, vahyin ortak mesajı, affın fazileti.", fazilet: "'İşlerini istişareyle yürütenler' mümin tanımındadır; yönetim ve aile kararı için okunur.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It emphasizes revelation, consultation (shura), and balanced response to wrong while trusting Allah.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد الوحي والشورى وحسن التعامل مع الإساءة مع التوكل على الله.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan wahyu, musyawarah (syura), dan respons seimbang terhadap kesalahan dengan tawakal.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ وحی، شوریٰ اور توکل کے ساتھ برائی کا متوازن جواب سکھاتی ہے۔" },
  { n: 43, ad: "Zuhruf", inis: "Mekke", konu: "Altın süslerin dünyanın süsü; İsa'nın kul olması beyanı.", fazilet: "Dünyanın geçiciliğini en berrak anlatan pasaj; mal ve itibar derdinde okunması güzeldir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It challenges attachment to ancestral error and affirms the Qur’an’s message and Jesus’s true status as a servant and sign.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تتحدى التقليد الأعمى وتؤكد رسالة القرآن ومكانة عيسى عبدا وآية.", nuzul_id: "Surah ini turun pada periode Mekah. Menantang ikut-ikutan leluhur yang keliru, menegaskan pesan Al-Qur’an dan kedudukan Isa sebagai hamba dan tanda.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ اندھی تقلید کو چیلنج کرتی ہے، قرآن کے پیغام اور عیسیٰ کی بندگی و نشانی کی حیثیت واضح کرتی ہے۔" },
  { n: 44, ad: "Duhân", inis: "Mekke", konu: "Kıyamet dumanı işareti; Kur'an'ın kutlu gecede indirilişi.", fazilet: "Kadir gecesi rahmetinden söz ettiği için kutlu gecelerde okunması güzeldir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It warns through the story of earlier communities and affirms the Qur’an as a reminder sent in a clear language.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تنذر بقصص الأمم السابقة وتؤكد القرآن ذكرا بلسان مبين.", nuzul_id: "Surah ini turun pada periode Mekah. Memperingatkan melalui kisah umat terdahulu dan menegaskan Al-Qur’an sebagai peringatan dengan bahasa jelas.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ سابق امتوں کے واقعات سے تنبیہ اور قرآن کو واضح زبان میں ذکر قرار دیتی ہے۔" },
  { n: 45, ad: "Câsiye", inis: "Mekke", konu: "Her milletin kendi elindeki kitaba çağrılması; kıyamet sırası.", fazilet: "Amel dosyasının bize gösterileceği bilinci kazandırır; amel muhasebesi okumasıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It invites reflection on signs in creation and warns about accountability on the Day all communities kneel.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدعو إلى التفكر في آيات الخلق وتحذر من مشهد الحساب يوم تجثو الأمم.", nuzul_id: "Surah ini turun pada periode Mekah. Mengajak merenungi tanda ciptaan dan memperingatkan hisab saat semua umat berlutut.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ تخلیق کی نشانیوں میں غور اور حساب کے دن کی تنبیہ دیتی ہے۔" },
  { n: 46, ad: "Ahkâf", inis: "Mekke", konu: "Ad halkının azabı; annesine iyi davranma vurgusu.", fazilet: "Anne hakkı beyanı ve sabır örneği; aile ahlakı okuması için iyidir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms truthfulness of revelation, respectful conduct toward parents, and the testimony of believing jinn as reported in the surah.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد صدق الوحي وحسن بر الوالدين وتذكر شهادة مؤمني الجن كما ورد في السورة.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan kebenaran wahyu, bakti kepada orang tua, dan kesaksian jin beriman sebagaimana dalam surah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ وحی کی سچائی، والدین سے حسن سلوک اور مومن جنوں کی گواہی کا ذکر کرتی ہے۔" },
  { n: 47, ad: "Muhammed", inis: "Medine", konu: "Cihad ahlakı; imanın engellere rağmen yükselişi.", fazilet: "Allah yolunda harcananın ekin misali kat kat karşılığı dersi; samimi imanın çıktısını öğretir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It sets guidance for believers in conflict and peace contexts, emphasizing sincerity, steadfastness, and reform.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تقدم هدى للمؤمنين في سياقات القتال والسلم مع الإخلاص والثبات والإصلاح.", nuzul_id: "Surah ini turun pada periode Madinah. Memberi panduan bagi Mukmin dalam konteks konflik dan damai, menekankan ikhlas, keteguhan, dan perbaikan.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ جنگ و صلح کے سیاق میں مومنوں کو اخلاص، ثبات اور اصلاح کی رہنمائی دیتی ہے۔" },
  { n: 48, ad: "Fetih", inis: "Medine", konu: "Hudeybiye barışı ve müjde; kalplerin seferberliği.", fazilet: "'Fetih yakındır' vaadi umut vericidir; sabır-dostluk dersini öğretir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It frames the Treaty of Hudaybiyyah context as a clear victory and calls to pledge, trust, and praise of Allah.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تؤطر صلح الحديبية فتحا مبينا وتدعو إلى البيعة والتوكل وتسبيح الله.", nuzul_id: "Surah ini turun pada periode Madinah. Membingkai konteks Perjanjian Hudaibiyah sebagai kemenangan nyata dan menyeru baiat, tawakal, dan pujian kepada Allah.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ صلح حدیبیہ کے سیاق کو فتح مبین قرار دیتی ہے، بیعت، توکل اور تسبیح کی دعوت دیتی ہے۔" },
  { n: 49, ad: "Hucurât", inis: "Medine", konu: "Asabiyet yasağı, gıybet, zanna dikkat; toplum birliği.", fazilet: "'Müminler kardeştir' ilkesi ve gıybet yasakları en net burada anlatılır.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It teaches community ethics: verifying news, avoiding mockery and suspicion, and understanding human diversity under taqwa.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تعلم أخلاق الجماعة: التثبت من الخبر واجتناب السخرية والظن، وفهم التنوع البشري ضمن التقوى.", nuzul_id: "Surah ini turun pada periode Madinah. Mengajarkan etika komunitas: tabayun, menjauhi olok-olok dan prasangka, serta memahami keragaman manusia dalam takwa.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ اجتماعی اخلاق سکھاتی ہے: تحقیق، تمسخر و بدگمانی سے اجتناب، تقویٰ میں انسانی تنوع کی سمجھ۔" },
  { n: 50, ad: "Kâf", inis: "Mekke", konu: "Kıyamet sorusu, ölüm gerçeği; rızık güvencesi.", fazilet: "'Üzerinizde iki bekçimizin yazdığı' bilinci kazandırır; ölüm ve hesap hatırlatmasında okunur.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It confronts denial of resurrection with observations of creation and the certainty of divine knowledge and judgment.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تواجه إنكار البعث بمشاهد الخلق ويقين علم الله والحساب.", nuzul_id: "Surah ini turun pada periode Mekah. Menghadapi penolakan kebangkitan dengan pengamatan ciptaan serta kepastian ilmu dan hisab Allah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ بعث کے انکار کا جواب تخلیق کے مشاہدات اور اللہ کے علم و حساب کے یقین سے دیتی ہے۔" },
  { n: 51, ad: "Zâriyât", inis: "Mekke", konu: "Toz savuran rüzgârlar yemini; tek Allah yaratıcıdır.", fazilet: "'Rızık arayın' öğretisi ile anneye-babaya iyilik dersleri tamamlanır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It swears by signs in creation to affirm resurrection and provision, calling to worship Allah alone.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقسم بآيات الخلق لتأكيد البعث والرزق وتدعو إلى عبادة الله وحده.", nuzul_id: "Surah ini turun pada periode Mekah. Bersumpah dengan tanda ciptaan untuk menegaskan kebangkitan dan rezeki, menyeru ibadah kepada Allah saja.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ تخلیق کی نشانیوں کی قسم کھا کر بعث و رزق کی تاکید اور خالص عبادت کی دعوت دیتی ہے۔" },
  { n: 52, ad: "Tûr", inis: "Mekke", konu: "Tûr dağı yemini; kıyamet sahneleri ve cennet betimlemeleri.", fazilet: "Cennet'te 'boş söz ve yalan duymazsınız' müjdesi; kıyamet bilinci tazelenir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms the coming judgment and contrasts the fate of deniers and the righteous in vivid scenes.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد وقوع الجزاء وتقابل مصير المكذبين والمتقين بمشاهد حية.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan datangnya pembalasan dan membandingkan nasib pendusta dan orang bertakwa.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ جزا کے وقوع کی تاکید اور جھٹلانے والوں و متقین کے انجام کا موازنہ کرتی ہے۔" },
  { n: 53, ad: "Necm", inis: "Mekke", konu: "İlk vahyin (Mirâc) gecesi; Lât, Uzzâ ve Menât putlarına tapmanın eleştirisi.", fazilet: "'Kıyamet bize yaklaştı' müjdesi; putlarla iman mücadelesinin dersidir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms the Prophet’s revelation and vision, rejects fabricated claims about angels, and calls to prostration to Allah.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تثبت وحي النبي ورؤياه وترفض الافتراءات حول الملائكة وتدعو إلى السجود لله.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan wahyu dan penglihatan Nabi, menolak klaim palsu tentang malaikat, dan menyeru sujud kepada Allah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ نبی کی وحی و رؤیت کی تصدیق، فرشتوں بارے جھوٹے دعووں کی تردید اور اللہ کو سجدے کی دعوت۔" },
  { n: 54, ad: "Kamer", inis: "Mekke", konu: "Ay'ın yarılması mucizesi; kıyamet gecesi sahneleri.", fazilet: "'Kolaylaştırdık' müjdesi dört kez tekrarlanır; hafızlığın en çok şevk ayetidir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It recalls the nearness of the Hour and the splitting of the moon sign in reports, urging reflection and warning.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تذكر اقتراب الساعة وآية انشقاق القمر كما تُروى، وتدعو إلى الاتعاظ.", nuzul_id: "Surah ini turun pada periode Mekah. Mengingatkan dekatnya Kiamat dan tanda terbelahnya bulan dalam riwayat, mengajak perenungan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قیامت کی قربت اور روایت کے مطابق شق القمر کی نشانی یاد دلا کر عبرت کی دعوت دیتی ہے۔" },
  { n: 57, ad: "Hadîd", inis: "Medine", konu: "Allah'ın her şeye gâlibliği; cihad ahlakı ve cömertlik.", fazilet: "'Mallarınızı Allah yolunda harcayın' çağrısı infak ahlakının temel kaynağı.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It urges faith, spending in Allah’s cause, and awareness that worldly life is temporary compared to the Hereafter.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تحث على الإيمان والإنفاق وتذكّر بأن الدنيا عابرة أمام الآخرة.", nuzul_id: "Surah ini turun pada periode Madinah. Mendorong iman, infak, dan kesadaran bahwa dunia sementara dibanding akhirat.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ ایمان، انفاق اور دنیا کی عارضیت بمقابلہ آخرت کی یاد دہانی کرتی ہے۔" },
  { n: 58, ad: "Mücâdele", inis: "Medine", konu: "Zıhâr meselesi ve aile hukuku; gizli toplantı ahlakı.", fazilet: "'Allah her şeyi işitir' bilinci özel toplantı ahlakını düzeltir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It addresses social disputes and proper conduct in assemblies and private counsel, emphasizing respect and taqwa.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تعالج جدال النساء وآداب المجالس والنجوى، مؤكدة الاحترام والتقوى.", nuzul_id: "Surah ini turun pada periode Madinah. Membahas sengketa dan adab majelis serta pembicaraan rahasia, menekankan hormat dan takwa.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ مباحثے، مجلسوں اور سرگوشی کے آداب بیان کرتی ہے، احترام و تقویٰ پر زور دیتی ہے۔" },
  { n: 59, ad: "Haşr", inis: "Medine", konu: "Benî Nadîr'in sürgünü; son üç ayette Allah'ın güzel isimlerinin sayılması.", fazilet: "Son üç ayette Allah'ın isimleri tek tek sayılır; bu ayetlerle dua etmek müstahap sayılır.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It reflects on the expulsion/banishment context of Banu Nadir and teaches lessons about reliance on Allah and community order.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تعرض سياق إخراج/حصار بني النضير وتعلم دروس التوكل ونظام الجماعة.", nuzul_id: "Surah ini turun pada periode Madinah. Mencerminkan konteks pengusiran Bani Nadhir dan mengajarkan tawakal serta ketertiban komunitas.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ بنو نضیر کے اخراج/محاصرے کے سیاق سے توکل اور اجتماعی نظم کے اسباق دیتی ہے۔" },
  { n: 60, ad: "Mümtehine", inis: "Medine", konu: "Düşmanlarla ilişki kuralları; İbrahim'in örneği.", fazilet: "İbrahim'in babası için duası (60:4), akrabaya şefkatle din emrinin birbirine karıştırılmamasını öğretir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It guides relations with those who are hostile versus those who are just, balancing loyalty to faith with fairness.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تهدي علاقة المؤمنين بمن عاداهم وبمن قسط إليهم، موازنة بين الولاء والإحسان.", nuzul_id: "Surah ini turun pada periode Madinah. Memberi panduan hubungan dengan pihak yang memusuhi dan yang berlaku adil, menyeimbangkan loyalitas iman dan keadilan.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ دشمن اور منصف لوگوں سے تعلقات میں ایمان کی وفاداری اور انصاف کا توازن سکھاتی ہے۔" },
  { n: 61, ad: "Saf", inis: "Medine", konu: "'Saf bağlayın' emri; İsa'nın müjdeci beyanı.", fazilet: "'İsâ, Meryem oğlu Allah'ın elçisidir' beyanıyla tevhid zinciri tamamlanır; cemaat birliğinin dersidir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It calls believers to align words with deeds and recalls support for truth through messengers.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تدعو إلى مطابقة القول للعمل وتذكر نصرة الحق بالرسل.", nuzul_id: "Surah ini turun pada periode Madinah. Menyeru kesesuaian ucapan dan perbuatan serta mengingat dukungan bagi kebenaran melalui rasul.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ قول و عمل کی مطابقت اور رسولوں کے ذریعے حق کی نصرت کی یاد دہانی کرتی ہے۔" },
  { n: 62, ad: "Cuma", inis: "Medine", konu: "Cuma ibadeti, bayram şeriatı; iş-güç düzeni mesajı.", fazilet: "Cuma günü okunması müekkedir; namaz bitince 'dağılın' çağrısı çalışma ahlakidir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It establishes Friday congregational prayer and balances worship with lawful pursuit after the prayer.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تشرع صلاة الجمعة وتوازن بين العبادة والسعي المشروع بعدها.", nuzul_id: "Surah ini turun pada periode Madinah. Menetapkan salat Jumat dan menyeimbangkan ibadah dengan usaha halal setelahnya.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ جمعہ کی نماز اور نماز کے بعد حلال کوشش کے توازن کو بیان کرتی ہے۔" },
  { n: 63, ad: "Münâfikûn", inis: "Medine", konu: "Münafıkların tanımı; yemini alet etme ve samimiyetsizlik.", fazilet: "Yemini ticarette alet eden münafık portresi; samimi davranış için okunması iyi.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It exposes hypocritical speech and behavior, urging sincerity, charity before death, and obedience to Allah.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تكشف كلام المنافقين وسلوكهم وتحث على الإخلاص والإنفاق قبل الموت.", nuzul_id: "Surah ini turun pada periode Madinah. Mengungkap ucapan dan perilaku munafik, mendorong ikhlas, infak sebelum mati, dan taat.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ منافقوں کے کلام و کردار کو ظاہر کرتی ہے، اخلاص، موت سے پہلے انفاق اور اطاعت کی ترغیب دیتی ہے۔" },
  { n: 64, ad: "Teğâbün", inis: "Medine", konu: "Kazanç-kayıp günü: kıyamette herkes gerçek kârını görür.", fazilet: "'Gâbûn' asıl âhiret günüdür müjdesi; iman edip salih amel işleyenlere iyi haber.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It reminds that gain and loss are ultimately tied to faith and response to Allah, encouraging forgiveness and mindful spending.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تذكر أن الربح والخسارة مرتبطان بالإيمان والاستجابة لله، وتشجع على العفو والإنفاق.", nuzul_id: "Surah ini turun pada periode Madinah. Mengingatkan untung-rugi hakiki terkait iman dan respons kepada Allah, mendorong maaf dan infak.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ نفع و نقصان کو ایمان اور اللہ کی پکار پر لبیک کہنے سے جوڑتی ہے، درگزر اور انفاق کی ترغیب دیتی ہے۔" },
  { n: 65, ad: "Talâk", inis: "Medine", konu: "Boşanma hukuku, iddet ve aile düzeni; takva sahiplerine çıkış yolu açılır.", fazilet: "'Kim Allah'tan korkarsa Allah ona bir çıkış yolu açar' müjdesi darlık dönemlerinin umut ayetidir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It gives guidance on divorce waiting periods and responsibilities, emphasizing taqwa and trust in Allah.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تنظم عدة الطلاق والمسؤوليات وتؤكد التقوى والتوكل على الله.", nuzul_id: "Surah ini turun pada periode Madinah. Memberi panduan iddah talak dan tanggung jawab, menekankan takwa dan tawakal.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ طلاق کی عدت اور ذمہ داریوں کی رہنمائی دیتی ہے، تقویٰ و توکل پر زور دیتی ہے۔" },
  { n: 66, ad: "Tahrîm", inis: "Medine", konu: "Hanımların imtihanı; tevbeye çağrı ve aile içi sorumluluk.", fazilet: "'Ailelerinizi cehennemden koruyun' sorumluluğu ebeveyn ahlakının temelidir.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It addresses household matters of the Prophet and calls believers to sincere repentance and steadfastness.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تعالج شؤون البيت النبوي وتدعو المؤمنين إلى توبة نصوح والثبات.", nuzul_id: "Surah ini turun pada periode Madinah. Membahas urusan rumah tangga Nabi dan menyeru tobat nasuha serta keteguhan.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ گھرِ نبوی کے امور اور مومنوں کو توبۂ نصوح و استقامت کی دعوت دیتی ہے۔" },
  { n: 68, ad: "Kalem", inis: "Mekke", konu: "Kaleme yemin; ehl-i bahçe imtihanı ve Yûnus kıssası.", fazilet: "Sabır ve tövbe dersleri; Yûnus'un darlık sabrı ve kavmine öğüdü umut verir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It defends the Prophet against slander, contrasts character, and warns by the parable of the garden owners.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدافع عن النبي ضد الافتراء وتقابل الأخلاق وتحذر بمثل أصحاب الجنة.", nuzul_id: "Surah ini turun pada periode Mekah. Membela Nabi dari fitnah, membandingkan akhlak, dan memperingatkan dengan perumpamaan pemilik kebun.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ نبی کی تردیدِ الزامات کرتی ہے، اخلاق کا موازنہ اور باغ والوں کی مثال سے تنبیہ دیتی ہے۔" },
  { n: 69, ad: "Hâkka", inis: "Mekke", konu: "Gerçek olan kıyamet; amel defterlerinin verilme sahnesi.", fazilet: "'Kitabı sağ elinden alana sevinç' sahnesi; hesap bilincini tazeler.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms the reality of the coming Hour and the truthfulness of revelation through accounts of past peoples.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد تحقق الساعة وصدق الوحي بذكر مصائر الأمم السابقة.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan kepastian Kiamat dan kebenaran wahyu melalui kisah umat terdahulu.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قیامت کی حقیقت اور وحی کی سچائی کو سابق امتوں کے انجام سے واضح کرتی ہے۔" },
  { n: 70, ad: "Meâric", inis: "Mekke", konu: "Yükselen melekler; sabır, namaz ve cömertlik dersi.", fazilet: "'İnsan sabırsız yaratıldı' tanısıyla sabır eğitimi okunur; dua ve istiğfar tavsiye edilir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It describes the Day of Judgment and qualities of those who seek protection from punishment through disciplined faith.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور يوم القيامة وصفات من يسعى للنجاة بإيمان منضبط.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan Hari Kiamat dan sifat orang yang beriman disiplin mencari keselamatan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ یومِ قیامت اور منضبط ایمان کے ساتھ نجات چاہنے والوں کی صفات بیان کرتی ہے۔" },
  { n: 71, ad: "Nûh", inis: "Mekke", konu: "Nûh peygamberin kavmine uzun davası ve yalvarışları.", fazilet: "Nûh'un 'günahımı affet' duası istiğfar tarzının modelini verir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It recounts Nuh’s persistent call, the rejection he faced, and the consequences of denial.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تحكي دعوة نوح المتواصلة وإعراض قومه وعاقبة التكذيب.", nuzul_id: "Surah ini turun pada periode Mekah. Menceritakan dakwah Nuh yang gigih, penolakan kaumnya, dan akibat pendustaan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ نوح کی مسلسل دعوت، قوم کی اعراض اور جھٹلانے کے انجام کو بیان کرتی ہے۔" },
  { n: 72, ad: "Cin", inis: "Mekke", konu: "Cinlerin Kur'an dinlemesi; vahyin evrenselliği.", fazilet: "Cinlerin Kur'an dinlemesi davetin evrenselliğini gösterir; gaybın anahtarı Allah'tadır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It reports the response of believing jinn to the Qur’an and affirms Allah’s exclusive right to be worshipped.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تنقل استجابة الجن المؤمنين للقرآن وتؤكد حق الله وحده في العبادة.", nuzul_id: "Surah ini turun pada periode Mekah. Menyampaikan respons jin Mukmin terhadap Al-Qur’an dan menegaskan hak ibadah hanya untuk Allah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ مومن جنوں کے قرآن پر ردعمل اور عبادت کے حقِ الٰہی کی تاکید کرتی ہے۔" },
  { n: 73, ad: "Müzzemmil", inis: "Mekke", konu: "Gece ibadet emri; Kur'an'ın ağır ağır (tertil) okunması.", fazilet: "'Kur'an'ı tertil ile oku' emri okuma ahlakının özü; gece ibadeti için ideal.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It prepares the Prophet for night prayer and patience in conveying the message under burden.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تهيئ النبي لقيام الليل والصبر على تبليغ الرسالة.", nuzul_id: "Surah ini turun pada periode Mekah. Mempersiapkan Nabi untuk salat malam dan sabar dalam menyampaikan risalah.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ نبی کو قیام اللیل اور تبلیغِ رسالت میں صبر کے لیے تیار کرتی ہے۔" },
  { n: 74, ad: "Müddessir", inis: "Mekke", konu: "Davet başlangıcı ve sorumluluk; cehennem sahnesi.", fazilet: "Davetin uyarı ve müjde için olduğu ders; davetçi eğitiminde en önemli surelerden.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It calls to arise and warn, purify, and remain patient, with scenes warning against denial.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدعو إلى القيام والإنذار والتطهر والصبر مع مشاهد تحذيرية.", nuzul_id: "Surah ini turun pada periode Mekah. Menyeru bangkit memperingatkan, menjaga kesucian, dan sabar, disertai peringatan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ اٹھ کر تنبیہ کرنے، پاکیزگی اور صبر کی دعوت دیتی ہے، انکار پر وعید کے ساتھ۔" },
  { n: 75, ad: "Kıyâmet", inis: "Mekke", konu: "Kıyamet günü insanın yetersizliği; ruhun sorumluluğu.", fazilet: "'İnsan o gün ancak kendi amelinden haberdar edilir' bilinci; ahiret sorumluluğunun özüdür.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms resurrection by oath and reflection on human creation and the certainty of judgment.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد البعث بالقسم والتفكر في خلق الإنسان ويقين الجزاء.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan kebangkitan dengan sumpah dan renungan penciptaan manusia serta kepastian hisab.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قسم اور انسانی تخلیق کے غور سے بعث و جزا کے یقین کو واضح کرتی ہے۔" },
  { n: 76, ad: "İnsân", inis: "Medine", konu: "İnsanın imtihanı; cömertliğin karşılığı olan cennet.", fazilet: "'Yetimlere, esirlere, yoksullara yemek vermek' — infak ahlakının sofra örneği.", nuzul: "İnsân (Dehr) suresinin iniş yeri hakkında Mekke ve Medine rivayetleri vardır. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It reflects on human choice, gratitude or denial, and describes outcomes for the righteous and deniers.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تتأمل خيار الإنسان بين الشكر والكفر وتعرض مصير الأبرار والمكذبين.", nuzul_id: "Surah ini turun pada periode Madinah. Merenungkan pilihan manusia antara syukur dan kufur serta menggambarkan akibat bagi Mukmin dan pendusta.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ انسان کے شکر یا کفر کے انتخاب اور نیکوں و جھٹلانے والوں کے انجام پر غور دلاتی ہے۔" },
  { n: 77, ad: "Mürselât", inis: "Mekke", konu: "Rüzgârlar yemini; kıyamet ve cennet tabloları.", fazilet: "Kıyamet serisinin ilk büyük sure; Peygamber'in kavmine son 'uyarı' mesajları.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It repeats warnings about the Day of Decision, calling to heed signs and consequences.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تكرر التحذير من يوم الفصل داعية إلى الاعتبار.", nuzul_id: "Surah ini turun pada periode Mekah. Mengulang peringatan tentang Hari Keputusan, mengajak mengambil pelajaran.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ یومِ فصل کی بار بار تنبیہ اور عبرت کی دعوت دیتی ہے۔" },
  { n: 79, ad: "Nâziât", inis: "Mekke", konu: "Canları koparıp alan melekler yemini; Mûsâ-Firavun karşılaşması.", fazilet: "'Rabbinin en büyük korkusundan sakınan...' mümin tanımı; kibirli gücün çöküşünü gösterir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It depicts scenes of resurrection and the fate of the arrogant and the God-fearing.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور مشاهد البعث ومصير الطغاة والمتقين.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan kebangkitan serta nasib orang zalim dan bertakwa.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ بعث کے مناظر اور سرکشوں و متقین کے انجام کو بیان کرتی ہے۔" },
  { n: 80, ad: "Abese", inis: "Mekke", konu: "Engelli bir kimsenin yüz çevrildiği olay ve Rabbin uyarısı.", fazilet: "Engelliye şefkati ve hakkını öğreten uyarı; merhamet okumasıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It teaches attentive respect toward those seeking guidance and warns against neglecting sincere seekers.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تعلم حسن الإصغاء لطالب الهداية وتحذر من الإعراض عن الساعي الصادق.", nuzul_id: "Surah ini turun pada periode Mekah. Mengajarkan perhatian kepada pencari petunjuk dan memperingatkan agar tidak mengabaikan mereka.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ ہدایت کے متلاشی کی قدر اور sincere طالب سے اعراض کی ممانعت سکھاتی ہے۔" },
  { n: 81, ad: "Tekvîr", inis: "Mekke", konu: "Güneş'in katlanması yemini; kıyamet tabloları.", fazilet: "'Kız çocuk diri diri gömüldüğünde sorulacak' — tarihî adalet dersi.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It portrays cosmic upheaval at the Hour and affirms the Qur’an as a conveyed revelation.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور اضطراب الكون عند الساعة وتؤكد القرآن وحيا مبلغا.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan guncangan kosmik saat Kiamat dan menegaskan Al-Qur’an sebagai wahyu yang disampaikan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قیامت کے وقت کائناتی ہلچل اور قرآن کی وحی ہونے کی تصدیق کرتی ہے۔" },
  { n: 82, ad: "İnfitâr", inis: "Mekke", konu: "Göğün yarılması; amel defterinin açılması.", fazilet: "Kim zerre ağırlınca şer işlerse görecektir — hesap anının bilinçli hatırlatması.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It describes the breaking of cosmic order and reminds each soul of what it sent ahead.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور انفطار النظام الكوني وتذكر كل نفس بما قدمت.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan runtuhnya tatanan kosmik dan mengingatkan setiap jiwa akan amalnya.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ کائناتی نظم کے بکھرنے اور ہر نفس کو اس کے اعمال کی یاد دہانی کرتی ہے۔" },
  { n: 83, ad: "Mutaffifîn", inis: "Mekke", konu: "Ölçüde hile edenlerin vay hâli; ticaret ahlakının merkezi.", fazilet: "Ölçü ve tartıda adalet emri; ticarette dürüstlüğün ahlaki temelidir.", nuzul: "Mutaffifîn suresinin iniş yeri hakkında Mekke ve Medine rivayetleri bulunur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "Reports differ about the place of revelation; tafsir literature discusses this. Some reports discuss Meccan or Medinan attribution; the surah condemns fraud in measure and affirms the record and judgment of deeds.", nuzul_ar: "تختلف الروايات في مكان نزولها. تُناقش نسبة نزولها، وتدين التطفيف وتؤكد كتاب الأعمال والحساب.", nuzul_id: "Riwayat berbeda tentang tempat turunnya. Sebagian riwayat membahas atribusi Mekah/Madinah; surah ini mengecam kecurangan takaran dan menegaskan catatan amal.", nuzul_ur: "اس کے مقام نزول میں روایات مختلف ہیں۔ نزول کے نسبت میں بحث ملتی ہے؛ ناپ تول میں کمی کی مذمت اور اعمال کے ریکارڈ و حساب کی تاکید کرتی ہے۔" },
  { n: 84, ad: "İnşikâk", inis: "Mekke", konu: "Göğün çatlaması; amel kitabını arkadaşından alanların vay hâli.", fazilet: "İnsanın amel bilincini kıyamet sahneleriyle uyaran okumadır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It depicts the sky’s submission to its Lord and the human meeting with deeds on the Day of Judgment.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور انشقاق السماء وخضوعها للرب وملاقاة الإنسان عمله يوم القيامة.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan langit terbelah tunduk kepada Tuhannya dan manusia menemui amalnya.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ آسمان کے پھٹنے اور انسان کے اپنے اعمال سے ملاقات کے مناظر بیان کرتی ہے۔" },
  { n: 85, ad: "Bürûc", inis: "Mekke", konu: "Burçlar yemini; hendeğe atılan müminlerin direnci (Ukhdûd).", fazilet: "Zalimin ezdiği müminlerin akibeti: 'Allah'ın azabı her tarafı kuşatmıştır' — sabır okuması.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It recalls the people of the trench and affirms Allah’s power, justice, and support for believers.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تذكر أصحاب الأخدود وتؤكد قدرة الله وعدله ونصر المؤمنين.", nuzul_id: "Surah ini turun pada periode Mekah. Mengingatkan Ashabul Ukhdud dan menegaskan kekuasaan, keadilan, serta dukungan Allah bagi Mukmin.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ اصحاب الاخدود کا ذکر، اللہ کی قدرت، عدل اور مومنوں کی نصرت کی تاکید کرتی ہے۔" },
  { n: 86, ad: "Târik", inis: "Mekke", konu: "Geceleyin gelen yıldız yemini; insanın yaratılış muhasebesi.", fazilet: "Her insanın 'koruyucu bekçisi' vardır — güvenlik bilinci kazandıran kısa sure.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms that every soul has a guardian and that resurrection is certain, by signs in creation.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد أن لكل نفس حافظا وأن البعث حق بدلالة الخلق.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan setiap jiwa ada penjaga dan kebangkitan pasti, melalui tanda ciptaan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ ہر نفس پر نگہبان اور بعث کی حقیقت کو تخلیقی دلائل سے واضح کرتی ہے۔" },
  { n: 87, ad: "A'lâ", inis: "Mekke", konu: "En Yüce Rabbin ismi; Kur'an'ı kolaylaştırma beyanı.", fazilet: "Cuma namazı, bayram ve cenaze namazlarında Peygamber'in okuduğu surelerden.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It calls to glorify Allah, reminds of success through purification, and notes the ease of the reminder.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تدعو إلى تسبيح الله وتذكر فلاح من تزكى وتيسير الذكرى.", nuzul_id: "Surah ini turun pada periode Mekah. Menyeru bertasbih, mengingat keberuntungan orang yang menyucikan diri, dan kemudahan pengingat.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ تسبیح، تزکیہ سے کامیابی اور ذکر کی آسانی کی طرف متوجہ کرتی ہے۔" },
  { n: 88, ad: "Ğâşiye", inis: "Mekke", konu: "Kaplayan olay (kıyamet); cennet ve cehennem tabloları.", fazilet: "Kıyamet tasviri ve 'onlara öğüt ver; sen ancak hatırlatan'sın mesajı.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It contrasts the state of the overwhelmed on that Day with the bliss of the successful, urging reflection.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقابل حال الأشقياء بالنعيم للناجين وتدعو إلى التفكر.", nuzul_id: "Surah ini turun pada periode Mekah. Membandingkan keadaan orang celaka dan kenikmatan orang beruntung, mengajak merenung.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ بدحال اور کامیاب لوگوں کے انجام کا موازنہ کر کے غور کی دعوت دیتی ہے۔" },
  { n: 89, ad: "Fecr", inis: "Mekke", konu: "Fecr ve on gece yemini; Âd-İrem ve Firavun akıbetleri.", fazilet: "'Ey huzura kavuşan nefis!' müjdesi — mutmain nefsin cennet çağrısının en net anlatımı.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It warns through destroyed peoples and calls to honor the vulnerable and a reassured soul returning to its Lord.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تحذر بمصارع أمم وتدعو إلى إكرام الضعيف والنفس المطمئنة.", nuzul_id: "Surah ini turun pada periode Mekah. Memperingatkan melalui kaum yang dibinasakan dan menyeru memuliakan yang lemah serta jiwa yang tenang.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ ہلاک قوموں سے تنبیہ، کمزوروں کی تکریم اور مطمئن نفس کی طرف دعوت دیتی ہے۔" },
  { n: 90, ad: "Beled", inis: "Mekke", konu: "Bu güvenli belde yemini; insanın zorlu yaşam imtihanı.", fazilet: "'Yokuşu aşmak kurtuluştur' — köle azat etmek, aç doyurmak ve sabır yolu listesi infak ahlakının özüdür.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It describes the human struggle and defines the steep path as freeing, feeding, and steadfast faith and compassion.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور كبد الإنسان وتعرف العقبة بالإعتاق والإطعام والإيمان والصبر والتراحم.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan perjuangan manusia dan jalan mendaki: memerdekakan, memberi makan, iman, sabar, dan kasih sayang.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ انسانی جدوجہد اور ‘عقبہ’ کو آزادی، کھلانے، ایمان، صبر اور رحمدلی سے تعبیر کرتی ہے۔" },
  { n: 91, ad: "Şems", inis: "Mekke", konu: "Güneş-ay ve gökyüzü yemini; Semûd'un dişi deveyi katletmesi.", fazilet: "'Allah korkusunu dışarıda bırakan helak oldu' — takva dersi kısa ve şifalıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It swears by cosmic signs and the soul, highlighting purification versus corruption and the consequence exemplified by Thamud.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقسم بآيات الكون والنفس وتبرز التزكية مقابل التدسية وعاقبة ثمود.", nuzul_id: "Surah ini turun pada periode Mekah. Bersumpah dengan tanda kosmos dan jiwa, menonjolkan pensucian lawan pengotoran serta akibat kaum Tsamud.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ کائناتی نشانیوں اور نفس کی قسم، تزکیہ بمقابلہ آلودگی اور ثمود کے انجام کو بیان کرتی ہے۔" },
  { n: 92, ad: "Leyl", inis: "Mekke", konu: "Gece erkek-dişi yaratılış yemini; cömertlik ve kanaat.", fazilet: "Gece-gündüz ikiliğiyle cömertlik ve takva dersi; infak ahlakının seçkin surelerinden.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It contrasts paths of generosity and taqwa with withholding and denial, and their outcomes.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقابل سبيل البذل والتقوى بسبيل البخل والتكذيب ومآلاتهما.", nuzul_id: "Surah ini turun pada periode Mekah. Membandingkan jalan derma dan takwa dengan kikir dan dusta serta akibatnya.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ سخاوت و تقویٰ کے راستے کو بخل و تکذیب کے راستے اور انجام سے مقابل کرتی ہے۔" },
  { n: 95, ad: "Tîn", inis: "Mekke", konu: "İncir-zeytin yemini; insanın en güzel yaratılışı.", fazilet: "'İnsanı en güzel biçimde yarattık' bilinci kendine saygı okumasıdır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It affirms human dignity in creation and warns that moral decline except for faith and good deeds leads to loss.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تؤكد تكريم الإنسان في الخلق وتحذر من الردة الأخلاقية إلا بالإيمان والعمل الصالح.", nuzul_id: "Surah ini turun pada periode Mekah. Menegaskan kemuliaan manusia dalam penciptaan dan memperingatkan kemerosotan moral tanpa iman-amal saleh.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ انسانی تکریم کی تاکید اور ایمان و نیک عمل کے بغیر اخلاقی گراوٹ سے خبردار کرتی ہے۔" },
  { n: 96, ad: "Alak", inis: "Mekke", konu: "Kur'an'ın ilk beş ayeti: 'Oku!' emri ve kan pıhtısından yaratılış.", fazilet: "Kur'an'ın ilk vahyi: okuma ve öğretmenin Allah'ın başlattığı emir; öğretmen günü mesajlarının dayanağı.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It begins with the command to read in the name of the Lord, marking the start of revelation and affirming knowledge and human accountability.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تفتتح بالأمر بالقراءة باسم الرب علامة بدء الوحي وتؤكد العلم والمسؤولية.", nuzul_id: "Surah ini turun pada periode Mekah. Dimulai dengan perintah membaca atas nama Tuhan, menandai awal wahyu serta menegaskan ilmu dan tanggung jawab.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ رب کے نام سے پڑھنے کے حکم سے وحی کے آغاز اور علم و ذمہ داری کی تاکید کرتی ہے۔" },
  { n: 98, ad: "Beyyine", inis: "Medine", konu: "Apaçık kanıt gelmesi; Kitap ehlinin ayırımı.", fazilet: "İman edip salih amel işleyen 'yaratılmışların hayırlısı' tanımını verir; amel ahlakının net ölçüsüdür.", nuzul: "Bu sure Medine döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Madinan period. It clarifies the clear proof brought by the Messenger and the essence of sincere worship and righteous deeds.", nuzul_ar: "نزلت هذه السورة في العهد المدني. تبين البينة التي جاء بها الرسول وجوهر العبادة المخلصة والعمل الصالح.", nuzul_id: "Surah ini turun pada periode Madinah. Menjelaskan bukti jelas yang dibawa Rasul dan inti ibadah ikhlas serta amal saleh.", nuzul_ur: "یہ سورت مدنی دور میں نازل ہوئی۔ رسول کی لائی ہوئی واضح دلیل اور خالص عبادت و نیک عمل کے جوہر کو بیان کرتی ہے۔" },
  { n: 100, ad: "Âdiyât", inis: "Mekke", konu: "Nefes nefese atların yemini; insanın mal sevgisi zaafı.", fazilet: "'İnsan Rabbine karşı çok nankördür' tanısı; mal sevgisinden şükre dönmeye çağırır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It depicts the human tendency to ingratitude and love of wealth, calling to awareness of accountability.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور نزوع الإنسان إلى الجحود وحب المال وتدعو إلى استحضار الحساب.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan kecenderungan manusia kufur nikmat dan cinta harta, menyeru kesadaran hisab.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ انسان کی ناشکری اور مال کی محبت کے رجحان کو دکھا کر حساب کی بیداری دلاتی ہے۔" },
  { n: 101, ad: "Kâria", inis: "Mekke", konu: "Varıp duran kıyamet; tartıdaki amel sahibi.", fazilet: "'Tartısı ağır gelenler mutlu hayattadır' müjdesi; amel tartısı mesajı işlenir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It portrays the Calamity and the weighing of deeds, stressing that outcomes depend on one’s balance of actions.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تصور القارعة ووزن الأعمال وتؤكد تعلق المصير بثقل العمل.", nuzul_id: "Surah ini turun pada periode Mekah. Menggambarkan al-Qari‘ah dan penimbangan amal, menekankan akibat sesuai timbangan perbuatan.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ قارعة اور اعمال کے تولے جانے کا منظر، انجام کو اعمال کے وزن سے جوڑتی ہے۔" },
  { n: 102, ad: "Tekâsür", inis: "Mekke", konu: "Çokluk yarışı oyaladı; mezara kadar göreceksiniz.", fazilet: "Dünya birikimi yarışının boşluğu; kısa ama etkili mesajlardır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It warns that rivalry in worldly increase distracts until the reality of the grave and accountability becomes clear.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تحذر من التكاثر واللهو حتى تتكشف حقيقة القبر والحساب.", nuzul_id: "Surah ini turun pada periode Mekah. Memperingatkan berlomba memperbanyak dunia hingga hakikat kubur dan hisab jelas.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ دنیوی تکاثر کی غفلت سے خبردار کرتی ہے یہاں تک کہ قبر و حساب کی حقیقت سامنے آئے۔" },
  { n: 104, ad: "Hümeze", inis: "Mekke", konu: "Alay eden ve mal toplayıp sayanların vay hâli.", fazilet: "Cimrilik ve alayın akıbeti cehennem ateşidir; mal sevgisinin çare olmadığı hatırlatılır.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It condemns backbiting, slander, and hoarding wealth as if it grants immortality, warning of crushing punishment.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تذم الهمز واللمز وكنز المال توهما للخلود وتحذر من العذاب.", nuzul_id: "Surah ini turun pada periode Mekah. Mengecam pengumpat, pencela, dan penimbun harta yang mengira kekal, memperingatkan azab.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ طعن، غیبت نما عیب جوئی اور مال جمع کر کے ہمیشہ رہنے کے گمان کی مذمت کرتی ہے۔" },
  { n: 111, ad: "Tebbet", inis: "Mekke", konu: "Ebû Leheb'in helaki; ona eşinin de katılması.", fazilet: "Peygamber'in düşmanlarına ilahi koruma müjdesi — ilk inen sureler arasında rivayet edilir.", nuzul: "Bu sure Mekke döneminde nazil olmuştur. Sure, ana konularını Kur’an’ın tevhid, ahiret ve ahlâk mesajı çerçevesinde ele alır; ayrıntılı nüzul sebepleri ve rivayet farklılıkları için güvenilir tefsir kaynaklarına başvurulmalıdır.", nuzul_en: "This surah was revealed in the Meccan period. It declares the fate of Abu Lahab and his wife as a warning tied to hostility against the message; details are reported in sirah/tafsir.", nuzul_ar: "نزلت هذه السورة في العهد المكي. تقرر مصير أبي لهب وامرأته عبرة مرتبطة بعداء الرسالة؛ وتُذكر التفاصيل في السيرة والتفسير.", nuzul_id: "Surah ini turun pada periode Mekah. Menyatakan nasib Abu Lahab dan istrinya sebagai peringatan terkait permusuhan terhadap risalah; rincian ada di sirah/tafsir.", nuzul_ur: "یہ سورت مکی دور میں نازل ہوئی۔ ابولہب اور اس کی زوجہ کے انجام کو پیغام کی دشمنی کے تناظر میں عبرت بتاتی ہے؛ تفصیل سیرت/تفسیر میں ہے۔" }
];
